        GraphResponse: components["schemas"]["BaseResponse"] & {
            data?: components["schemas"]["GraphView"];
        };
        PublicProfileResponse: components["schemas"]["BaseResponse"] & {
            data?: components["schemas"]["PublicProfileView"];
        };
