    attemptNegotiation: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "offerId": "672a0fa1b2c3d40012345600",
                 *       "amount": 75,
                 *       "quantity": 2
                 *     }
                 */
                "application/json": components["schemas"]["NegotiationAttemptRequest"];
            };
        };
        responses: {
            /** @description Negotiation accepted (price within band, wallet covered any charge). */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "success": true,
                     *       "message": "Negotiation successful.",
                     *       "data": {
                     *         "isNegotiable": true,
                     *         "attemptsLeft": 2,
                     *         "isFree": true,
                     *         "attemptCount": 1,
                     *         "chargedThisAttempt": 0,
                     *         "nextAttemptCost": 0,
                     *         "chargeFormula": {
                     *           "base": 10,
                     *           "jumpMultiplier": 5
                     *         }
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["NegotiationAttemptResponse"];
                };
            };
            /**
             * @description Bid was out of range. **The attempt STILL counted** —
             *     `attemptCount` reflects the newly-incremented value and
             *     `chargedThisAttempt` shows what was debited (0 while in
             *     the free window). Also returned when the offer is no
             *     longer available for negotiation (BLOCKED / INACTIVE /
             *     SOLD_OUT), in which case nothing was counted or
             *     charged — read the `message` to disambiguate.
             */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "success": true,
                     *       "message": "Proposed amount is not within acceptable range.",
                     *       "data": {
                     *         "isNegotiable": false,
                     *         "attemptsLeft": 0,
                     *         "isFree": false,
                     *         "attemptCount": 5,
                     *         "chargedThisAttempt": 50,
                     *         "nextAttemptCost": 100,
                     *         "chargeFormula": {
                     *           "base": 10,
                     *           "jumpMultiplier": 5
                     *         }
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["NegotiationAttemptResponse"];
                };
            };
            401: components["responses"]["Unauthorized"];
            /** @description Insufficient O balance to cover the current attempt's tier charge. */
            402: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            422: components["responses"]["ValidationError"];
            500: components["responses"]["ServerError"];
        };
    };
