    globalSearch: {
        parameters: {
            query: {
                /**
                 * @description Search text. Minimum 2 characters — a single character matches most
                 *     of the corpus, so serving it costs a near-full scan to return
                 *     noise. The client holds the request until the field has two
                 *     characters; this is the server-side half of that contract.
                 * @example sunset
                 */
                q: string;
                /**
                 * @description Results **per entity kind**, not in total. This is a typeahead —
                 *     the shell shows a handful per group and hands the rest to
                 *     Discovery — so the cap is low on purpose.
                 * @example 6
                 */
                limit?: number;
                /**
                 * @description Narrow to one kind. Omitted (the shell's own case) searches all
                 *     three. A `kind` filter skips the other branches entirely rather
                 *     than running and discarding them, so a section's scoped search does
                 *     not cost the same as the global one.
                 * @example creators
                 */
                kind?: "weos" | "circles" | "creators";
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Ranked results, grouped by kind */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "success": true,
                     *       "message": "Search results retrieved successfully",
                     *       "data": {
                     *         "query": "sunset",
                     *         "weos": [
                     *           {
                     *             "id": "651f8c2a3b9c0d12e4567890",
                     *             "slug": "sunset-drop-03",
                     *             "title": "Sunset Drop 03",
                     *             "weoType": "regular",
                     *             "categoryName": "Digital arts",
                     *             "creatorName": "janedoe",
                     *             "mediaUrl": "https://cdn.weo.example/w/sunset-03.jpg",
                     *             "score": 2.4
                     *           }
                     *         ],
                     *         "circles": [
                     *           {
                     *             "id": "651f8c2a3b9c0d12e4567891",
                     *             "slug": "digital-arts",
                     *             "name": "Digital Arts",
                     *             "axisLabel": "By Category",
                     *             "coverColor": "#1F2937",
                     *             "coverImage": "",
                     *             "memberCount": 1240,
                     *             "score": 1.1
                     *           }
                     *         ],
                     *         "creators": [
                     *           {
                     *             "id": "651f8c2a3b9c0d12e4567892",
                     *             "name": "sunsetstudio",
                     *             "handle": "@sunsetstudio",
                     *             "avatarUrl": "https://cdn.weo.example/u/651f8c2a.jpg",
                     *             "followersCount": 318,
                     *             "tier": "player",
                     *             "isr": 78
                     *           }
                     *         ],
                     *         "total": 3
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["GlobalSearchResponse"];
                };
            };
            401: components["responses"]["Unauthorized"];
            422: components["responses"]["ValidationError"];
            500: components["responses"]["ServerError"];
        };
    };
