    resellWeo: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description Source WeO (the previous holder's Offer being resold). */
                id: components["schemas"]["ObjectId"];
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "title": "Field Notes",
                 *       "description": "Three notebooks, unopened.",
                 *       "amountOs": 2180,
                 *       "quantity": 3,
                 *       "tags": [
                 *         "paper"
                 *       ],
                 *       "collectionId": "66b1f0c2a1b2c3d4e5f60719"
                 *     }
                 */
                "application/json": {
                    title: string;
                    description: string;
                    /** @description The ask in Os. Wins over `amount`. */
                    amountOs?: number;
                    /** @description Legacy ask in US dollars (`price.amount` units). */
                    amount?: number;
                    quantity: number;
                    tags?: string[];
                    collectionId?: components["schemas"]["ObjectId"];
                };
            };
        };
        responses: {
            /** @description Resold offer created. */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["BaseResponse"] & {
                        data?: {
                            /** @description The newly created resold-offer doc. */
                            resold: Record<string, never>;
                            /** @description WeoResell audit row. */
                            resellAudit: Record<string, never>;
                        };
                    };
                };
            };
            /** @description Bad body OR offer not resellable OR collection not fully paid. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            401: components["responses"]["Unauthorized"];
            /** @description Caller has not collected this WeO. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description Source WeO not found. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description Caller has already resold this collection row, or it is disputed. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            500: components["responses"]["ServerError"];
        };
    };
    resellQuote: {
        parameters: {
            query?: {
                /** @description Quote this holding (default — the oldest not yet relisted). */
                collectionId?: components["schemas"]["ObjectId"];
            };
            header?: never;
            path: {
                id: components["schemas"]["ObjectId"];
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Quote. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "success": true,
                     *       "message": "Resell quote",
                     *       "data": {
                     *         "weoId": "66b1f0c2a1b2c3d4e5f60718",
                     *         "collectionId": "66b1f0c2a1b2c3d4e5f60719",
                     *         "resellable": true,
                     *         "blockers": [],
                     *         "title": "Field Notes",
                     *         "description": "Three notebooks",
                     *         "img": "https://cdn.example/a.jpg",
                     *         "format": "Listing",
                     *         "tags": [
                     *           "paper"
                     *         ],
                     *         "quantity": 3,
                     *         "unitName": "books",
                     *         "paidOs": 1980,
                     *         "valueOs": 1980,
                     *         "dial": {
                     *           "start": 2180,
                     *           "min": 990,
                     *           "max": 4750,
                     *           "lo": 1880,
                     *           "hi": 2970,
                     *           "step": 10
                     *         },
                     *         "usdAgainstO": 99,
                     *         "fees": []
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["BaseResponse"] & {
                        data?: {
                            weoId: components["schemas"]["ObjectId"];
                            collectionId: components["schemas"]["ObjectId"] | null;
                            resellable: boolean;
                            blockers: {
                                /** @enum {string} */
                                code: "not_resellable" | "not_held" | "already_relisted" | "unpaid" | "disputed";
                                message: string;
                            }[];
                            title: string;
                            description: string;
                            img: string | null;
                            /** @enum {string} */
                            format: "Listing" | "Drop" | "Bid" | "Pool" | "Hunt";
                            tags: string[];
                            /** @description Units per WeO as listed — the POST quantity. */
                            quantity: number;
                            unitName: string;
                            /** @description Os paid (or owed in full) for this holding. */
                            paidOs: number | null;
                            /** @description The WeO's current price in Os. */
                            valueOs: number;
                            dial: {
                                start: number;
                                min: number;
                                max: number;
                                /** @description Lower edge of the band most likely to clear. */
                                lo: number;
                                hi: number;
                                step: number;
                            };
                            usdAgainstO: number;
                            fees: unknown[];
                        };
                    };
                };
            };
            401: components["responses"]["Unauthorized"];
            /** @description WeO not found. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            422: components["responses"]["ValidationError"];
            500: components["responses"]["ServerError"];
        };
    };
