    listWeos: {
        parameters: {
            query?: {
                /** @description Optional. Omit to list across all kinds. */
                weoType?: components["schemas"]["WeoType"];
                /**
                 * @description 1-based page number.
                 * @example 1
                 */
                page?: components["parameters"]["PageParam"];
                /**
                 * @description Items per page (capped at 100).
                 * @example 20
                 */
                limit?: components["parameters"]["LimitParam"];
                /**
                 * @description Free-text substring filter; semantics vary per endpoint.
                 * @example jane
                 */
                search?: components["parameters"]["SearchParam"];
                categoryId?: components["schemas"]["ObjectId"];
                creatorId?: components["schemas"]["ObjectId"];
                /**
                 * @description Per-kind enum. Validated by the kind-specific service when
                 *     `weoType` is set; ignored otherwise.
                 */
                status?: string;
                /**
                 * @description * `recent`      — newest first (`createdAt` desc).
                 *     * `trending`    — `activeNow` desc, then `participantsCount`
                 *       desc, then `createdAt` desc. Leads on `activeNow` (distinct
                 *       viewers in the last 24h) because Discovery's "Moving now" rail
                 *       promises ranking by who is in the room rather than by all-time
                 *       popularity; `participantsCount` is a lifetime total and answers
                 *       the opposite question, so it breaks ties among the many rows
                 *       sharing an `activeNow` of 0.
                 *     * `ending_soon` — soonest close time first, ascending on the
                 *       row's `closesAt` (see the response schema). Rows with no
                 *       close time, and rows whose close time has already passed,
                 *       are EXCLUDED from the result rather than sorted to the
                 *       end — so `total` under this sort counts only rows that
                 *       can still close.
                 *
                 *     When `search` is also set, relevance leads and `sort` breaks
                 *     ties; `ending_soon` is the exception — its ordering is
                 *     resolved by a dedicated aggregation, so relevance does not
                 *     reorder it.
                 */
                sort?: "recent" | "trending" | "ending_soon";
                /**
                 * @description Feed scope. `following` narrows the list to WeOs created by
                 *     users the authenticated caller follows.
                 *
                 *     Orthogonal to `sort`, `status` and paging, so
                 *     `?feed=following&sort=trending` reads as "what's trending
                 *     among the creators I follow". Combining it with `creatorId`
                 *     intersects the two: that creator if they are followed,
                 *     nobody otherwise.
                 *
                 *     A caller who is unauthenticated, or who follows nobody, gets
                 *     **200 with an empty page** — following nobody is a state,
                 *     not a failure.
                 */
                feed?: "following";
                /**
                 * @description Inclusive lower bound. Compared against the row's
                 *     kind-specific price field (see the endpoint description).
                 */
                minPrice?: number;
                /**
                 * @description Inclusive upper bound. Compared against the row's
                 *     kind-specific price field (see the endpoint description).
                 */
                maxPrice?: number;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Paginated WeOs. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["WeoListResponse"];
                };
            };
            401: components["responses"]["Unauthorized"];
            422: components["responses"]["ValidationError"];
            500: components["responses"]["ServerError"];
        };
    };
