    updateWeo: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                id: components["schemas"]["ObjectId"];
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["UpdateWeoRequest"];
            };
        };
        responses: {
            /**
             * @description WeO updated. `data` is the raw kind-specific document
             *     (Offer / Crowdfund / Lottery) — same polymorphic `Weo`
             *     shape returned by `POST /weos`. On regular's versioning
             *     path, `_id` is the newly-created version's id and the
             *     archived predecessor's id lives in `parentOfferId`.
             */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["WeoResponse"];
                };
            };
            /**
             * @description Malformed WeO id, payload `weoType` doesn't match the
             *     target doc's actual `weoType`, or the kind's edit gate
             *     fired (crowdfund past first contribution, lottery past
             *     first ticket sale).
             */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            401: components["responses"]["Unauthorized"];
            /**
             * @description Caller is not the crowdfund/lottery owner. Regular
             *     uses 404 instead (owner-scoped query — deliberate,
             *     hides existence).
             */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            /**
             * @description WeO not found. For the regular arm this also covers
             *     wrong-owner (message uniformly
             *     `"Offer not found or unauthorized"`).
             */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponse"];
                };
            };
            422: components["responses"]["ValidationError"];
            500: components["responses"]["ServerError"];
        };
    };
